[{"type": "legacy_vis", "embeddableConfig": {"savedVis": {"title": "Service Availability", "description": "", "type": "vega", "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Service Availability: successful \u00f7 (successful + failed) transactions, excluding google* health checks and transactions with no recorded outcome. Speedometer with its trend underneath. Hover anywhere over the trend for that interval.",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": {
    "left": 6,
    "right": 10,
    "top": 4,
    "bottom": 2
  },
  "signals": [
    {
      "name": "lo",
      "value": 0.98
    },
    {
      "name": "hi",
      "value": 1
    },
    {
      "name": "amber",
      "value": 0.99
    },
    {
      "name": "green",
      "value": 0.995
    },
    {
      "name": "gaugeH",
      "update": "height * 0.5"
    },
    {
      "name": "cx",
      "update": "width / 2"
    },
    {
      "name": "r",
      "update": "max(10, min(width / 2 - 8, gaugeH - 6))"
    },
    {
      "name": "muted",
      "value": "#98a2b3"
    },
    {
      "name": "hov",
      "value": null,
      "on": [
        {
          "events": "@cell:mouseover",
          "update": "datum.datum"
        },
        {
          "events": "@cell:mouseout",
          "update": "null"
        },
        {
          "events": "mouseout",
          "update": "null"
        }
      ]
    }
  ],
  "data": [
    {
      "name": "buckets",
      "url": {
        "index": "traces-apm*",
        "body": {
          "size": 0,
          "query": {
            "bool": {
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "@timestamp": {
                      "%timefilter%": true
                    }
                  }
                },
                {
                  "term": {
                    "processor.event": "transaction"
                  }
                },
                {
                  "terms": {
                    "event.outcome": [
                      "success",
                      "failure"
                    ]
                  }
                }
              ],
              "filter": [
                "%dashboard_context-filter_clause%"
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%",
                {
                  "wildcard": {
                    "transaction.name": "google*"
                  }
                }
              ]
            }
          },
          "aggs": {
            "t": {
              "date_histogram": {
                "field": "@timestamp",
                "interval": {
                  "%autointerval%": 48
                },
                "min_doc_count": 0,
                "extended_bounds": {
                  "min": {
                    "%timefilter%": "min"
                  },
                  "max": {
                    "%timefilter%": "max"
                  }
                }
              },
              "aggs": {
                "ok": {
                  "filter": {
                    "term": {
                      "event.outcome": "success"
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.t.buckets"
      }
    },
    {
      "name": "rows",
      "source": "buckets",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.doc_count > 0"
        },
        {
          "type": "formula",
          "as": "avail",
          "expr": "datum.ok.doc_count / datum.doc_count"
        },
        {
          "type": "formula",
          "as": "t",
          "expr": "toDate(datum.key)"
        }
      ]
    },
    {
      "name": "overall",
      "source": "buckets",
      "transform": [
        {
          "type": "formula",
          "as": "ok",
          "expr": "datum.ok.doc_count"
        },
        {
          "type": "aggregate",
          "fields": [
            "doc_count",
            "ok"
          ],
          "ops": [
            "sum",
            "sum"
          ],
          "as": [
            "total",
            "okSum"
          ]
        },
        {
          "type": "filter",
          "expr": "datum.total > 0"
        },
        {
          "type": "formula",
          "as": "avail",
          "expr": "datum.okSum / datum.total"
        },
        {
          "type": "formula",
          "as": "ang",
          "expr": "-PI / 2 + PI * clamp((datum.avail - lo) / (hi - lo), 0, 1)"
        },
        {
          "type": "formula",
          "as": "colour",
          "expr": "datum.avail >= green ? '#1f9e6b' : datum.avail >= amber ? '#c98a0b' : '#d6453d'"
        }
      ]
    },
    {
      "name": "bands",
      "values": [
        {
          "a": 0.98,
          "b": 0.99,
          "c": "#d6453d"
        },
        {
          "a": 0.99,
          "b": 0.995,
          "c": "#c98a0b"
        },
        {
          "a": 0.995,
          "b": 1,
          "c": "#1f9e6b"
        }
      ]
    },
    {
      "name": "thresholds",
      "values": [
        {
          "v": 0.99,
          "c": "#c98a0b"
        },
        {
          "v": 0.995,
          "c": "#1f9e6b"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "time",
      "domain": {
        "data": "rows",
        "field": "t"
      },
      "range": [
        0,
        {
          "signal": "width"
        }
      ]
    },
    {
      "name": "y",
      "type": "linear",
      "zero": false,
      "nice": true,
      "domain": {
        "fields": [
          {
            "data": "rows",
            "field": "avail"
          },
          {
            "data": "thresholds",
            "field": "v"
          }
        ]
      },
      "range": [
        {
          "signal": "height - 18"
        },
        {
          "signal": "gaugeH + 16"
        }
      ]
    }
  ],
  "axes": [
    {
      "orient": "bottom",
      "scale": "x",
      "offset": {
        "signal": "-18"
      },
      "tickCount": 4,
      "labelColor": {
        "signal": "muted"
      },
      "domain": false,
      "ticks": false,
      "labelFontSize": 10,
      "labelPadding": 4
    },
    {
      "orient": "left",
      "scale": "y",
      "tickCount": 3,
      "format": ".1%",
      "labelColor": {
        "signal": "muted"
      },
      "domain": false,
      "ticks": false,
      "grid": true,
      "gridOpacity": 0.15,
      "labelFontSize": 10
    }
  ],
  "marks": [
    {
      "type": "arc",
      "from": {
        "data": "bands"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "cx"
          },
          "y": {
            "signal": "gaugeH"
          },
          "innerRadius": {
            "signal": "r * 0.9"
          },
          "outerRadius": {
            "signal": "r * 0.97"
          },
          "startAngle": {
            "signal": "-PI / 2 + PI * (datum.a - lo) / (hi - lo)"
          },
          "endAngle": {
            "signal": "-PI / 2 + PI * (datum.b - lo) / (hi - lo)"
          },
          "fill": {
            "field": "c"
          },
          "opacity": {
            "value": 0.9
          }
        }
      }
    },
    {
      "type": "arc",
      "encode": {
        "update": {
          "x": {
            "signal": "cx"
          },
          "y": {
            "signal": "gaugeH"
          },
          "innerRadius": {
            "signal": "r * 0.68"
          },
          "outerRadius": {
            "signal": "r * 0.84"
          },
          "startAngle": {
            "signal": "-PI / 2"
          },
          "endAngle": {
            "signal": "PI / 2"
          },
          "fill": {
            "value": "#8a96a8"
          },
          "opacity": {
            "value": 0.18
          }
        }
      }
    },
    {
      "type": "arc",
      "from": {
        "data": "overall"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "cx"
          },
          "y": {
            "signal": "gaugeH"
          },
          "innerRadius": {
            "signal": "r * 0.68"
          },
          "outerRadius": {
            "signal": "r * 0.84"
          },
          "startAngle": {
            "signal": "-PI / 2"
          },
          "endAngle": {
            "field": "ang"
          },
          "fill": {
            "field": "colour"
          },
          "tooltip": {
            "signal": "{'Availability (selected range)': format(datum.avail, '.2%'), 'Successful': format(datum.okSum, ','), 'Transactions': format(datum.total, ',')}"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "overall"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "cx"
          },
          "y": {
            "signal": "gaugeH - 2"
          },
          "text": {
            "signal": "format(datum.avail, '.2%')"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "bottom"
          },
          "fontSize": {
            "signal": "max(12, r * 0.25)"
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "field": "colour"
          },
          "tooltip": {
            "signal": "{'Availability (selected range)': format(datum.avail, '.2%'), 'Successful': format(datum.okSum, ','), 'Transactions': format(datum.total, ',')}"
          }
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": {
            "signal": "cx - r * 0.93"
          },
          "y": {
            "signal": "gaugeH + 12"
          },
          "text": {
            "value": "98%"
          },
          "align": {
            "value": "center"
          },
          "fontSize": {
            "value": 10
          },
          "fill": {
            "signal": "muted"
          }
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": {
            "signal": "cx + r * 0.93"
          },
          "y": {
            "signal": "gaugeH + 12"
          },
          "text": {
            "value": "100%"
          },
          "align": {
            "value": "center"
          },
          "fontSize": {
            "value": 10
          },
          "fill": {
            "signal": "muted"
          }
        }
      }
    },
    {
      "type": "rule",
      "from": {
        "data": "thresholds"
      },
      "encode": {
        "update": {
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "scale": "y",
            "field": "v"
          },
          "stroke": {
            "field": "c"
          },
          "strokeDash": {
            "value": [
              4,
              4
            ]
          },
          "strokeOpacity": {
            "value": 0.8
          }
        }
      }
    },
    {
      "type": "area",
      "from": {
        "data": "rows"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "t"
          },
          "y": {
            "scale": "y",
            "field": "avail"
          },
          "y2": {
            "signal": "height - 18"
          },
          "fill": {
            "value": "#3987e5"
          },
          "fillOpacity": {
            "value": 0.15
          },
          "interpolate": {
            "value": "monotone"
          }
        }
      },
      "interactive": false
    },
    {
      "type": "line",
      "from": {
        "data": "rows"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "t"
          },
          "y": {
            "scale": "y",
            "field": "avail"
          },
          "stroke": {
            "value": "#3987e5"
          },
          "strokeWidth": {
            "value": 2
          },
          "interpolate": {
            "value": "monotone"
          }
        }
      },
      "interactive": false
    },
    {
      "type": "rule",
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "signal": "hov ? scale('x', hov.t) : -10"
          },
          "x2": {
            "signal": "hov ? scale('x', hov.t) : -10"
          },
          "y": {
            "signal": "gaugeH + 16"
          },
          "y2": {
            "signal": "height - 18"
          },
          "stroke": {
            "signal": "muted"
          },
          "strokeOpacity": {
            "signal": "hov ? 0.7 : 0"
          },
          "strokeWidth": {
            "value": 1
          }
        }
      }
    },
    {
      "type": "symbol",
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "signal": "hov ? scale('x', hov.t) : -10"
          },
          "y": {
            "signal": "hov ? scale('y', hov.avail) : -10"
          },
          "size": {
            "value": 50
          },
          "fill": {
            "value": "#3987e5"
          },
          "stroke": {
            "value": "#ffffff"
          },
          "strokeWidth": {
            "value": 1.5
          },
          "opacity": {
            "signal": "hov ? 1 : 0"
          }
        }
      }
    },
    {
      "type": "symbol",
      "name": "pts",
      "interactive": false,
      "from": {
        "data": "rows"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "t"
          },
          "y": {
            "scale": "y",
            "field": "avail"
          },
          "size": {
            "value": 1
          },
          "fill": {
            "value": "transparent"
          }
        }
      }
    },
    {
      "type": "path",
      "name": "cell",
      "from": {
        "data": "pts"
      },
      "encode": {
        "update": {
          "fill": {
            "value": "transparent"
          },
          "stroke": {
            "value": "transparent"
          },
          "tooltip": {
            "signal": "{'Time': timeFormat(datum.datum.t, '%b %d %H:%M'), 'Availability': format(datum.datum.avail, '.2%'), 'Transactions': format(datum.datum.doc_count, ',')}"
          }
        }
      },
      "transform": [
        {
          "type": "voronoi",
          "x": "datum.x",
          "y": "datum.y",
          "extent": {
            "signal": "[[0, gaugeH + 8], [width, height]]"
          }
        }
      ]
    }
  ]
}"}, "uiState": {}, "data": {"aggs": [], "searchSource": {"query": {"query": "", "language": "kuery"}, "filter": []}}}, "title": "Service Availability", "description": "Successful ÷ (successful + failed) transactions across every service, excluding google* health checks and transactions with no recorded outcome (event.outcome "unknown"). The speedometer shows the selected time range, the line its trend. Red below 99 %, amber 99–99.5 %, green 99.5 % and above. Follows the time picker and the dashboard controls."}, "panelIndex": "9590f1da-8625-5896-bd17-1ed156586bfa", "gridData": {"y": 0, "x": 34, "w": 14, "h": 17, "i": "9590f1da-8625-5896-bd17-1ed156586bfa", "sectionId": "f4f2d342-1b96-5bba-8a34-fbe85e81e9f0"}}, {"type": "vis", "embeddableConfig": {"time_range": {"from": "now-1M", "to": "now"}, "title": "Active Incidents", "description": "Active P1 and P2 incidents (state not Resolved, Closed, Canceled or Cancelled). SLA = the worst ServiceNow SLA on the incident: Breached, Breaching (75 % used or due within 30 min), Paused (On-Hold), Within SLA or Met. "(age)" = no SLA record found, so age is compared with P1 4 h / P2 8 h; this also happens while a CI Name or Incident control is set, because the SLA records carry neither field. Click an Incident or an Affected CI to open it in ServiceNow. Last 1 month (fixed).", "attributes": {"title": "Active Incidents", "references": [], "state": {"datasourceStates": {"textBased": {"layers": {"fa649954-2993-4275-9376-b242edb174c0": {"index": "9f62b314bfcb4761b36fe6855dfe7db7ae32e2921b803c93eb14be7838e0cd93", "query": {"esql": "FROM servicenow-incidents-*, servicenow-task-sla-* METADATA _index
| EVAL src = CASE(_index LIKE "*task-sla*", "sla", "inc")
| EVAL inc = CASE(src == "sla", TO_STRING(task_number), TO_STRING(number))
| WHERE inc LIKE "INC*"
| EVAL is_active = CASE(src == "inc" AND TO_INTEGER(priority) IN (1, 2) AND TO_STRING(state_name) NOT IN ("Resolved", "Closed", "Canceled", "Cancelled"), 1, 0)
| WHERE src == "sla" OR is_active == 1
| EVAL sla_stage = TO_LOWER(TO_STRING(stage))
| EVAL sla_kind = CASE(TO_LOWER(TO_STRING(contract_name)) LIKE "*respon*", "Response", "Resolution")
| EVAL sla_breached = COALESCE(TO_BOOLEAN(task_has_breached), false) OR sla_stage == "breached"
      OR (sla_stage == "in_progress" AND TO_DATETIME(planned_end_time) < NOW())
| EVAL sla_rank = CASE(
      sla_breached, 1,
      sla_stage == "in_progress" AND (TO_DOUBLE(percentage) >= 75 OR TO_DATETIME(planned_end_time) <= NOW() + 30 minutes), 2,
      sla_stage == "paused", 3,
      sla_stage == "in_progress", 4,
      5)
| EVAL sla_rank = CASE(src == "sla" AND sla_stage != "cancelled", sla_rank)
| STATS active = MAX(is_active), priority = MAX(TO_INTEGER(priority)), ci = VALUES(TO_STRING(ci.name)),
        state = VALUES(TO_STRING(state_name)), grp = VALUES(TO_STRING(assignment_group.name)),
        opened_at = MAX(TO_DATETIME(opened_at)), descr = VALUES(TO_STRING(short_description)), worst = MIN(sla_rank)
  BY inc
| WHERE active == 1
| EVAL age_minutes = DATE_DIFF("minutes", opened_at, NOW())
| EVAL _d = age_minutes / 1440, _h = (age_minutes % 1440) / 60, _m = age_minutes % 60
| EVAL age = CASE(
      _d > 0, CONCAT(TO_STRING(_d), " d ", TO_STRING(_h), " h ", TO_STRING(_m), " min"),
      _h > 0, CONCAT(TO_STRING(_h), " h ", TO_STRING(_m), " min"),
      CONCAT(TO_STRING(_m), " min"))
| EVAL target = CASE(priority == 1, 240, 480)
| EVAL sla = CASE(
      worst == 1, "Breached", worst == 2, "Breaching", worst == 3, "Paused", worst == 4, "Within SLA", worst == 5, "Met",
      age_minutes >= target, "Breached (age)", age_minutes >= target * 0.8, "At risk (age)", "Within SLA (age)")
| SORT priority ASC, age_minutes DESC
| RENAME inc AS number, ci AS ci.name, state AS state_name, grp AS assignment_group.name, descr AS short_description
| KEEP number, priority, ci.name, state_name, sla, assignment_group.name, opened_at, age, short_description"}, "columns": [{"columnId": "number", "fieldName": "number", "label": "Incident", "customLabel": true, "meta": {"type": "string", "esType": "keyword"}}, {"columnId": "6733b736-f585-445a-8c8a-4225361dd16d", "fieldName": "priority", "meta": {"type": "number", "esType": "integer"}, "label": "Priority", "customLabel": true}, {"columnId": "ci.name", "fieldName": "ci.name", "label": "Affected CI", "customLabel": true, "meta": {"type": "string", "esType": "keyword"}}, {"columnId": "23d1bad5-9618-4670-967a-cab3b7c6a4b5", "fieldName": "state_name", "meta": {"type": "string", "esType": "keyword", "params": {"id": "string"}}, "label": "State", "customLabel": true, "inMetricDimension": true}, {"columnId": "sla", "fieldName": "sla", "label": "SLA", "customLabel": true, "meta": {"type": "string", "esType": "keyword"}, "inMetricDimension": true}, {"columnId": "assignment_group.name", "fieldName": "assignment_group.name", "label": "Assignment Group", "customLabel": true, "meta": {"type": "string", "esType": "keyword"}, "inMetricDimension": true}, {"columnId": "a09c9d38-6160-4c6e-8e8d-c29e705d219a", "fieldName": "opened_at", "meta": {"type": "date", "esType": "date", "params": {"id": "date"}}, "label": "Opened", "customLabel": true, "inMetricDimension": true}, {"columnId": "380e7903-1e14-4354-bda5-96fea94d90c3", "fieldName": "age", "meta": {"type": "string", "esType": "keyword"}, "label": "Age", "customLabel": true, "inMetricDimension": true}, {"columnId": "3622e23d-9f64-4198-88ce-83004de6cac4", "fieldName": "short_description", "meta": {"type": "string", "esType": "keyword", "params": {"id": "string"}}, "label": "Short Description", "customLabel": true, "inMetricDimension": true}], "timeField": "@timestamp", "allColumns": [{"columnId": "number", "fieldName": "number", "label": "Incident", "customLabel": true, "meta": {"type": "string", "esType": "keyword"}}, {"columnId": "673